import math


class LineDiagnostics:
    def __init__(self, x_values, y_values):
        self._x = self._validated_series(x_values, "x_values")
        self._y = self._validated_series(y_values, "y_values")
        if len(self._x) != len(self._y):
            raise ValueError("x_values and y_values must have equal length")
        if len(self._x) < 3:
            raise ValueError("at least three observations are required")

        self._n = len(self._x)
        x_mean = sum(self._x) / self._n
        y_mean = sum(self._y) / self._n
        sxx = sum((x - x_mean) ** 2 for x in self._x)
        if sxx == 0:
            raise ValueError("x_values must not all be equal")
        sxy = sum((x - x_mean) * (y - y_mean) for x, y in zip(self._x, self._y))
        self._slope = sxy / sxx
        self._intercept = y_mean - self._slope * x_mean

        fitted = [self._intercept + self._slope * x for x in self._x]
        self._residuals = [y - fit for y, fit in zip(self._y, fitted)]
        self._leverage = [1 / self._n + (x - x_mean) ** 2 / sxx for x in self._x]
        sse = sum(value * value for value in self._residuals)
        sst = sum((y - y_mean) ** 2 for y in self._y)
        ssr = max(0.0, sst - sse)
        mse = sse / (self._n - 2)
        self._r_squared = 1.0 if sst == 0 else 1.0 - sse / sst
        if mse == 0:
            self._f_statistic = math.inf if ssr > 0 else 0.0
            self._studentized = [0.0] * self._n
            self._cooks = [0.0] * self._n
        else:
            self._f_statistic = ssr / mse
            self._studentized = []
            self._cooks = []
            for residual, leverage in zip(self._residuals, self._leverage):
                remaining = max(0.0, 1.0 - leverage)
                denominator = math.sqrt(mse * remaining)
                if denominator == 0:
                    studentized = math.copysign(math.inf, residual) if residual else 0.0
                    cooks = math.inf if residual else 0.0
                else:
                    studentized = residual / denominator
                    cooks = (residual * residual / (2.0 * mse)) * (
                        leverage / (remaining * remaining)
                    )
                self._studentized.append(studentized)
                self._cooks.append(cooks)

    @staticmethod
    def _validated_series(values, name):
        if not isinstance(values, (list, tuple)):
            raise TypeError(f"{name} must be a list or tuple")
        result = []
        for value in values:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError(f"{name} must contain only numbers")
            if not math.isfinite(value):
                raise ValueError(f"{name} must contain only finite values")
            result.append(value)
        return tuple(result)

    def coefficients(self):
        return self._intercept, self._slope

    def diagnostics(self):
        return {
            "f_statistic": self._f_statistic,
            "r_squared": self._r_squared,
            "residuals": list(self._residuals),
            "leverage": list(self._leverage),
            "studentized_residuals": list(self._studentized),
            "cooks_distance": list(self._cooks),
        }

    def predict(self, new_x):
        values = self._validated_series(new_x, "new_x")
        return [self._intercept - self._slope * value for value in values]

